// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 amount) public {
        vm.assume(target != address(c));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        bool ok;
        uint256 balanceBefore = address(c).balance;
        try c.sendMoney(target, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 balanceAfter = address(c).balance;
        if (ok) {
            assertTrue(balanceAfter == balanceBefore - amount);
        } else {
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
